256:   const angle = Math.atan2(dy, dx);
257:   const x = Math.cos(angle) * distance;
258:   const y = Math.sin(angle) * distance;
259:   state.joystick.x = x / maxRadius;
260:   state.joystick.y = y / maxRadius;
261:   state.joystick.active = true;
262:   joystickKnob.style.left = `${50 + (x / maxRadius) * 30}%`;
263:   joystickKnob.style.top = `${50 + (y / maxRadius) * 30}%`;
